seen=set(); out=[row[:] for row in g]
for r in range(13):
 for c in range(13):
  if g[r][c]==0 and (r,c) not in seen:
   st=[(r,c)];seen.add((r,c));co=[]
   while st:
    x,y=st.pop();co.append((x,y))
    for dx,dy in [(1,0),(-1,0),(0,1),(0,-1)]:
     q=(x+dx,y+dy)
     if 0<=q[0]<13 and 0<=q[1]<13 and g[q[0]][q[1]]==0 and q not in seen:seen.add(q);st.append(q)
   if len(co)>1:
    for x,y in co:out[x][y]=8
